          ["width", "Bridge middle width", 15, 100, 1, "%"],
          ["thickness", "Bridge middle thickness", 15, 100, 1, "%"],
          ["curvature", "Waist contraction", 0, 100, 1, "%"],
          ["smoothness", "Shoulder softness", 0, 100, 1, "%"],
          ["maxConnections", "Maximum neighboring letters", 1, 8, 1, ""],
