      <mesh geometry={geometry}>
        <meshStandardMaterial color={color} roughness={0.7} metalness={0.02} />
      </mesh>
      {/* Label marker — diagnostic only, not geometry */}
      <mesh position={[0, 2, 0]} visible={false} userData={{ fidelityLabel: label }} />
    </group>
